head.script:
scwin.trigger1_onclick = function(e) {
    input1.setMaxLength("");
};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 inputbox에 9자리의 값을 입력한다.
    //1. After executing the sample, input 9-digit value in inputbox.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('input1').focus()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('input1').setValue('123456789')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('input1').blur()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. 6자리까지만 입력되어진다.
    //1. Only up to 6 digits can be entered.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('input1').getValue()", "123456");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 'setMaxLength('');'버튼을 클릭 후 추가로 값을 입력한다. 
    //2. Click the 'setMaxLength (' ');' button, and then enter additional values.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('input1').focus()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('input1').setValue('123456789')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('input1').blur()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. 자리수 제한없이 값이 추가로 입력되어진다. (이전에는 6자리까지만 입력되어짐)
    //2. The value is entered without any limit. (Previously only up to 6 digits)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('input1').getValue()", "123456789");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 08-Mar-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
